import { ExtensionsSection } from "./components/extensions-section";
import { FAQ } from "./components/faq";
import { Footer } from "./components/footer";
import { HowItWorks } from "./components/how-it-works";
import { LandingHeader } from "./components/landing-header";
import { LandingHero } from "./components/landing-hero";
import { LandingPricing } from "./components/landing-pricing";
import { LandingStats } from "./components/landing-stats";
import { WhySaveIt } from "./components/why-saveit";

export function App() {
  return (
    <div className="landing-page min-h-screen">
      <LandingHeader />
      <main>
        <LandingHero />
        <LandingStats />
        <WhySaveIt />
        <HowItWorks />
        <ExtensionsSection />
        <LandingPricing />
        <FAQ />
      </main>
      <Footer />
    </div>
  );
}

import tailwindcss from "@tailwindcss/vite";
import react from "@vitejs/plugin-react";
import { defineConfig } from "vite";

export default defineConfig({
  plugins: [react(), tailwindcss()],
  server: {
    host: "127.0.0.1",
    strictPort: true,
  },
});

@import "tailwindcss";
@import "@fontsource-variable/geist";

@source "./**/*.{ts,tsx}";

:root {
  font-family: "Geist Variable", sans-serif;
  color: #fafafa;
  background: #141414;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  --font-elegant: Georgia, "Times New Roman", serif;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background: #141414;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

.font-elegant {
  font-family: var(--font-elegant);
}

.landing-page {
  position: relative;
  overflow: hidden;
  background: #141414;
  color: #fafafa;
}

.landing-page::before {
  position: fixed;
  z-index: 0;
  inset: 0;
  pointer-events: none;
  content: "";
  opacity: 0.04;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)'/%3E%3C/svg%3E");
  background-repeat: repeat;
  background-size: 256px 256px;
}

.landing-page > * {
  position: relative;
  z-index: 1;
}

const faqs = [
  {
    question: 'What does "agentic" mean?',
    answer:
      "Agentic AI doesn't just respond - it acts autonomously. While most AI tools wait for you to give commands, agentic systems make decisions and take action on their own. Your SaveIt agent automatically organizes your bookmarks, learns your patterns, and retrieves content before you even search.",
  },
  {
    question: "Can I cancel any time?",
    answer:
      "Yes. Manage or cancel from the billing provider you used. Pro stays active until the end of your current billing period.",
  },
  {
    question: "Do I have a limit?",
    answer:
      "Free includes up to 20 bookmarks, 20 AI bookmark runs, and 10 chat questions each month. Pro includes up to 50,000 bookmarks, 1,500 AI runs, and 200 chat questions each month.",
  },
  {
    question: "How to upgrade my plan?",
    answer:
      "Choose Upgrade to Pro during setup or from the pricing page, sign in to the account you want to upgrade, then complete the secure checkout.",
  },
  {
    question: "Is my data sent to any server?",
    answer:
      "Yes, your bookmarks are stored on our servers so you can access them from any device. We use encryption and never share your data with third parties.",
  },
  {
    question: "Do you offer refunds?",
    answer:
      "Yes, we offer a 7-day refund guarantee. Just contact hi@saveit.now and get an instant refund. No questions asked.",
  },
];

export const FAQ = () => {
  return (
    <section className="mx-auto max-w-5xl px-4 py-20 lg:py-28">
      <h2 className="font-elegant text-4xl tracking-tight text-[#fafafa] md:text-5xl">
        Questions <em>& answers</em>
      </h2>

      <div className="mt-12 grid gap-x-16 gap-y-10 md:grid-cols-2">
        {faqs.map((faq) => (
          <div key={faq.question}>
            <h3 className="text-[15px] font-medium text-[#fafafa]">
              {faq.question}
            </h3>
            <p className="mt-3 text-sm leading-relaxed text-[#888]">
              {faq.answer}
            </p>
          </div>
        ))}
      </div>
    </section>
  );
};

import { CheckIcon } from "lucide-react";

const tiers = [
  {
    name: "Free",
    id: "tier-free",
    href: "/signin?intent=signup",
    priceMonthly: "$0",
    description:
      "Perfect for getting started with bookmarking and organizing your digital content.",
    features: [
      "20 bookmarks",
      "Chrome extension",
    ],
    featured: false,
  },
  {
    name: "Pro",
    id: "tier-pro",
    href: "/upgrade",
    priceMonthly: "$5",
    description:
      "Everything you need to organize your digital knowledge with advanced features.",
    features: [
      "Up to 50,000 bookmarks",
      "API Access",
      "Export to CSV",
      "Priority support",
    ],
    featured: true,
  },
];

export const LandingPricing = () => {
  return (
    <section className="mx-auto max-w-5xl px-4 py-20 lg:py-28">
      <p className="text-sm text-[#666] mb-4">007 - Pricing</p>

      <div>
        <h2 className="font-elegant text-4xl md:text-5xl tracking-tight text-[#fafafa]">
          Choose the right plan <em>for you</em>
        </h2>
      </div>

      <p className="mt-6 max-w-2xl text-base text-[#888]">
        Start for free, upgrade when you need more. No hidden fees, just great
        features for organizing your digital knowledge.
      </p>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-px rounded-xl border border-[#2a2a2a] overflow-hidden mt-16">
        {tiers.map((tier, tierIdx) => (
          <div
            key={tier.id}
            className={`bg-[#1a1a1a] p-8 ${tierIdx === 0 && !tier.featured ? "lg:border-r border-[#2a2a2a]" : ""}`}
          >
            <h3 id={tier.id} className="text-base font-medium text-[#fafafa]">
              {tier.name}
            </h3>

            <p className="mt-4 flex items-baseline gap-x-2">
              <span className="text-5xl font-semibold tracking-tight text-[#fafafa]">
                {tier.priceMonthly}
              </span>
              <span className="text-[#666]">/month</span>
            </p>
            {tier.featured ? (
              <p className="mt-2 text-xs text-[#666]">Billed annually</p>
            ) : null}

            <p className="mt-6 text-base text-[#888]">{tier.description}</p>

            <ul
              role="list"
              className="mt-8 space-y-3 text-sm text-[#888] sm:mt-10"
            >
              {tier.features.map((feature) => (
                <li key={feature} className="flex gap-x-3">
                  <CheckIcon
                    aria-hidden="true"
                    className="h-6 w-5 flex-none text-[#fafafa]"
                  />
                  {feature}
                </li>
              ))}
            </ul>

            <a
              href={tier.href}
              aria-describedby={tier.id}
              className={`mt-8 inline-flex h-10 items-center justify-center rounded-full px-6 text-sm font-medium w-full text-center transition-colors ${
                tier.featured
                  ? "bg-[#fafafa] text-[#141414] hover:bg-[#e0e0e0]"
                  : "border border-white/10 text-[#fafafa] hover:bg-white/5"
              }`}
            >
              {tier.featured ? "Upgrade to Pro" : "Get Started Free"}
            </a>
          </div>
        ))}
      </div>
    </section>
  );
};

import type { ReactNode } from "react";

type LandingAppButtonProps = {
  authIntent?: "signin" | "signup";
  children?: ReactNode;
  className?: string;
  showAlwaysOpenPrompt?: boolean;
  signedOutChildren?: ReactNode;
  variant?: "default" | "outline";
};

export function LandingAppButton({
  authIntent = "signup",
  children = "Open SaveIt.now",
  className = "",
  signedOutChildren,
  variant = "default",
}: LandingAppButtonProps) {
  const base =
    "inline-flex h-9 items-center justify-center rounded-full px-4 text-sm font-medium transition-colors";
  const appearance =
    variant === "outline"
      ? "border border-white/10 bg-transparent text-[#fafafa] hover:bg-white/5"
      : "bg-[#fafafa] text-[#141414] hover:bg-[#e0e0e0]";

  return (
    <a
      className={`${base} ${appearance} ${className}`}
      href={`/signin?intent=${authIntent}&step=email`}
    >
      {signedOutChildren ?? children}
    </a>
  );
}

