@import "tailwindcss";
@import "@fontsource-variable/geist";

@source "./**/*.{ts,tsx}";

:root {
  font-family: "Geist Variable", ui-sans-serif, system-ui, sans-serif;
  color: #fff6ec;
  background: #100b08;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  --font-elegant: Georgia, "Times New Roman", serif;
  --ink: #100b08;
  --ink-2: #1a120c;
  --cream: #fff6ec;
  --sand: #f3d9bd;
  --muted: #c9b3a1;
  --faint: #8f7a6b;
  --ember: #ff5a1f;
  --ember-soft: #ff8a5c;
  --gold: #ffc36b;
  --moss: #9db98a;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background: var(--ink);
  color: var(--cream);
  overflow-x: hidden;
}

::selection {
  background: #ff5a1f;
  color: #fff6ec;
}

.font-elegant {
  font-family: var(--font-elegant);
}

.landing-page {
  position: relative;
  overflow-x: clip;
  background:
    radial-gradient(1200px 600px at 80% -10%, rgba(255, 90, 31, 0.16), transparent 60%),
    radial-gradient(900px 500px at 10% 20%, rgba(255, 195, 107, 0.08), transparent 60%),
    #100b08;
  color: var(--cream);
}

.landing-page::before {
  position: fixed;
  z-index: 0;
  inset: 0;
  pointer-events: none;
  content: "";
  opacity: 0.05;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)'/%3E%3C/svg%3E");
  background-repeat: repeat;
  background-size: 256px 256px;
}

.landing-page > * {
  position: relative;
  z-index: 1;
}

.skip-link {
  position: absolute;
  left: 1rem;
  top: -4rem;
  z-index: 100;
  background: #fff6ec;
  color: #100b08;
  padding: 0.75rem 1.25rem;
  border-radius: 999px;
  font-weight: 600;
  transition: top 0.2s ease;
}

.skip-link:focus {
  top: 1rem;
}

a:focus-visible,
button:focus-visible {
  outline: 2px solid #ffc36b;
  outline-offset: 3px;
  border-radius: 6px;
}

.display-xl {
  font-family: var(--font-elegant);
  letter-spacing: -0.03em;
  line-height: 0.95;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--gold);
}

.eyebrow::before {
  content: "";
  width: 1.75rem;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--gold));
}

.btn-primary {
  display: inline-flex;
  min-height: 3rem;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  border-radius: 999px;
  background: linear-gradient(135deg, #ff5a1f, #ff8a3d);
  color: #fff6ec;
  font-weight: 600;
  font-size: 0.95rem;
  padding: 0 1.75rem;
  box-shadow: 0 12px 40px -8px rgba(255, 90, 31, 0.55);
  transition: transform 0.25s ease, box-shadow 0.25s ease, filter 0.25s ease;
}

.btn-primary:hover {
  transform: translateY(-2px);
  filter: brightness(1.06);
  box-shadow: 0 18px 50px -8px rgba(255, 90, 31, 0.65);
}

.btn-ghost {
  display: inline-flex;
  min-height: 3rem;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  border-radius: 999px;
  border: 1px solid rgba(255, 246, 236, 0.2);
  color: var(--cream);
  font-weight: 500;
  font-size: 0.95rem;
  padding: 0 1.75rem;
  background: rgba(255, 246, 236, 0.04);
  backdrop-filter: blur(8px);
  transition: background 0.25s ease, transform 0.25s ease, border-color 0.25s ease;
}

.btn-ghost:hover {
  background: rgba(255, 246, 236, 0.1);
  border-color: rgba(255, 246, 236, 0.35);
  transform: translateY(-2px);
}

.card {
  background: linear-gradient(180deg, rgba(255, 246, 236, 0.07), rgba(255, 246, 236, 0.02));
  border: 1px solid rgba(255, 246, 236, 0.12);
  backdrop-filter: blur(12px);
}

.reveal {
  opacity: 0;
  transform: translateY(28px);
  transition: opacity 0.8s ease, transform 0.8s cubic-bezier(0.22, 1, 0.36, 1);
}

.reveal.is-visible {
  opacity: 1;
  transform: none;
}

.marquee {
  overflow: hidden;
  mask-image: linear-gradient(90deg, transparent, black 8%, black 92%, transparent);
}

.marquee-track {
  display: flex;
  gap: 3rem;
  width: max-content;
  animation: marquee 28s linear infinite;
}

@keyframes marquee {
  to {
    transform: translateX(-50%);
  }
}

@keyframes floaty {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-10px);
  }
}

.floaty {
  animation: floaty 6s ease-in-out infinite;
}

.hero-img-frame {
  box-shadow:
    0 40px 120px -20px rgba(0, 0, 0, 0.8),
    0 0 0 1px rgba(255, 246, 236, 0.12),
    0 0 80px -20px rgba(255, 90, 31, 0.35);
}

.workflow-tab {
  transition: background 0.3s ease, border-color 0.3s ease, transform 0.3s ease;
}

.workflow-tab[data-active="true"] {
  background: rgba(255, 90, 31, 0.12);
  border-color: rgba(255, 90, 31, 0.5);
}

.faq-panel {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows 0.4s cubic-bezier(0.22, 1, 0.36, 1);
}

.faq-panel[data-open="true"] {
  grid-template-rows: 1fr;
}

.faq-inner {
  overflow: hidden;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  .reveal {
    opacity: 1;
    transform: none;
    transition: none;
  }
  .marquee-track,
  .floaty {
    animation: none;
  }
  *,
  *::before,
  *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}

