  box-shadow:
    0 40px 120px -20px rgba(0, 0, 0, 0.8),
    0 0 0 1px rgba(255, 246, 236, 0.12),
    0 0 80px -20px rgba(255, 90, 31, 0.35);
}

.workflow-tab {
  transition: background 0.3s ease, border-color 0.3s ease, transform 0.3s ease;
}

